var MongoDB = require('mongodb');
var MongoClient = MongoDB.MongoClient;
const ObjectID = MongoDB.ObjectID;

var Config = require('./config.js');

class Db {

    static getInstance() {

        if (!Db.instance) {
            Db.instance = new Db();
        }
        return Db.instance;
    }

    constructor() {

        this.dbClient = '';
        this.connect();

    }

    connect() {
        let _that = this;
        return new Promise((resolve, reject) => {
            if (!_that.dbClient) {
                MongoClient.connect(Config.dbUrl, { useNewUrlParser: true, useUnifiedTopology: true }, (err, client) => {

                    if (err) {
                        reject(err)

                    } else {

                        _that.dbClient = client.db(Config.dbName);
                        resolve(_that.dbClient)
                    }
                })

            } else {
                resolve(_that.dbClient);

            }


        })

    }

    find(collectionName, json1, json2, json3) {

        if (arguments.length == 2) { //当传入2个参数时，查询指定参数这一条数据
            var attr = {};
            var skipNum = 0;
            var pageSize = 0;
            // db.user.find().skip(0).limit(0) //查询出所有数据
        } else if (arguments.length == 3) {  //查询一列或多列
            var attr = json2;
            var skipNum = 0;
            var pageSize = 0;
            // db.user.find({},json2).skip(0).limit(0) //查询出json2指定的一列
        } else if (arguments.length == 4) {  //实现数据库分页显示
            var attr = json2;
            var page = json3.page || 1;             //当前页或默认第一页
            var pageSize = json3.pageSize || 20;     //每一页的条数或默认每页20条
            var skipNum = (page - 1) * pageSize;
            //判断是否排序
            if (json3.sortJson) {
                var sortJson = json3.sortJson;
            } else {
                var sortJson = {};
            }
        } else {
            console.log("参数错误")
        }

        return new Promise((resolve, reject) => {

            this.connect().then((db) => {

                //var result = db.collection(collectionName).find(json);
                var result = db.collection(collectionName).find(json1, { filters: attr }).skip(skipNum).limit(pageSize).sort(sortJson);

                result.toArray(function (err, docs) {

                    if (err) {
                        reject(err);
                        return;
                    }
                    resolve(docs);
                })

            })
        })
    }

    insert(collectionName, json) {
        return new Promise((resolve, reject) => {
            this.connect().then((db) => {

                db.collection(collectionName).insertOne(json, function (err, result) {
                    if (err) {
                        reject(err);
                    } else {

                        resolve(result);
                    }
                })


            })
        })
    }


    getObjectId(id) {   //�õ����ݿ�"_id"

        return new ObjectID(id);
    }

    count(collectionName, json) {
        return new Promise((resolve, reject) => {
            this.connect().then((db) => {

                db.collection(collectionName).find(json).count(function (err, result) {
                    if (err) {
                        reject(err);
                    } else {

                        resolve(result);
                    }
                })


            })
        })
    }

    insert(collectionName, json) {
        return new Promise((resolve, reject) => {
            this.connect().then((db) => {

                db.collection(collectionName).insertOne(json, function (err, result) {
                    if (err) {
                        reject(err);
                    } else {

                        resolve(result);
                    }
                })


            })
        })
    }
}


module.exports = Db.getInstance();

var Router = require('koa-router');
var router = new Router();
var url = require('url');   //过滤url里？后面的内容

var login = require('./admin/login.js');
var list = require('./admin/list.js');
var index = require('./admin/index.js');


//配置中间件，获取url地址router.use([path], middleware) ⇒ Router， middleware为中间件，和koa的用法相同
router.use(async (ctx, next) => {

    //模板引擎配置全局变量__HOST__
    ctx.state.__HOST__ = 'http://' + ctx.request.header.host;
    var path = url.parse(ctx.request.url).pathname.substring(1);
    var splitUrl = path.split('/');

    //用于退出登陆
    ctx.state.G = {
        url: splitUrl,
        userinfo: ctx.session.userinfo,
        prevPage:ctx.request.headers['referer'] //得到前一个页面
    }


    //console.log(ctx.url)    //  /admin
    //权限判断，如果有权限，则可以访问，没有跳转到登陆页面
    if (ctx.session.userinfo) {
        await next();  //有了这个，才可向下运行
    } else {

        //如果当前页面不是登陆页面的话跳转到登陆页面，否则继续向下匹配
        if (path == 'admin/login' || path == 'admin/login/doLogin' ) {
            await next();

        } else {
            ctx.redirect('/admin/login');
        }

    }

})
//默认加载后台首页
router.use(list);

//配置层级路由
router.use('/login', login);
router.use('/index', index);


module.exports = router.routes();

var Router = require('koa-router');
var router = new Router();
var DB = require('../../model/db.js');

router.get('/', async (ctx) => {

    var page = ctx.query.page || 1;  //得到显示第几页
    var pageSize = 12;           //设置每页12条数据

    var result = await DB.find('ntzx', {}, {}, {
        page: page,
        pageSize: pageSize,
        sortJson: {
            "school": -1
        }
    });
    var count = await DB.count('ntzx', {});
    //渲染模板
    await ctx.render('admin/index', {
        list: result,
        page: page,
        totalPages: Math.ceil(count / pageSize)

    });

})
module.exports = router.routes();

